-- 1. Ensure Table Schema Exists (Idempotent)
CREATE TABLE IF NOT EXISTS pantone_colors (
    id INT AUTO_INCREMENT PRIMARY KEY,
    pantone_name VARCHAR(100) NOT NULL UNIQUE,
    pantone_code VARCHAR(50) NOT NULL,
    unique_code VARCHAR(50) NULL,
    hex_code VARCHAR(10) NOT NULL,
    red INT NOT NULL,
    green INT NOT NULL,
    blue INT NOT NULL,
    lab_l DECIMAL(6, 2) NULL,
    lab_a DECIMAL(6, 2) NULL,
    lab_b DECIMAL(6, 2) NULL,
    color_system VARCHAR(50) DEFAULT 'PMS Coated',
    status ENUM('active', 'inactive') DEFAULT 'active',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_pantone_code (pantone_code),
    INDEX idx_pantone_name (pantone_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

